"""What a user may upload (generated by Shikshya, PX.301): the types this app takes, read from the file's own bytes and
never from its name or the browser's word for it, and a size cap. Every upload goes through check_upload: the API's
file fields (api/picture_field.py) answer a clear 400, and the storages (config/storage.py) refuse a file that comes in
any other way (the admin, a view of the app's own). config/urls.py serves every upload as a download, never as a page.
UPLOAD_MAX_MB in the environment changes the size cap."""
import csv
import io
import os
import re
import zipfile

from django.core.exceptions import ValidationError

# The types the plan allows for file fields; picture fields always take images (api/picture_field.py).
ALLOWED = ('pdf', 'image')
STORED = ('pdf', 'image')
MAX_MB = int(os.getenv('UPLOAD_MAX_MB') or 10)

NAMES = {'pdf': 'PDF', 'image': 'image', 'csv': 'CSV', 'docx': 'Word (.docx)'}
EXTENSIONS = {
    'pdf': ('.pdf',),
    'image': ('.png', '.jpg', '.jpeg', '.gif', '.webp'),
    'csv': ('.csv',),
    'docx': ('.docx',),
}
# A spreadsheet runs a cell that starts with one of these as a formula (CSV injection).
FORMULA_SIGNS = ('=', '@', '+', '-', '\t', '\r')
MAX_ZIP_ENTRIES = 2000
MAX_ZIP_BYTES = 100 * 1024 * 1024
MAX_PART_BYTES = 2 * 1024 * 1024
RELATIONSHIP_RE = re.compile(r'<Relationship\b[^>]*>')
EXTERNAL_RE = re.compile(r"""TargetMode\s*=\s*["']External["']""")
HYPERLINK_RE = re.compile(r"""Type\s*=\s*["'][^"']*/hyperlink["']""")


def allowed_text(kinds=None):
    """The rule in words: 'Only PDF or image files up to 10 MB can be uploaded.'"""
    names = [NAMES[k] for k in (kinds or ALLOWED)]
    joined = names[0] if len(names) == 1 else ', '.join(names[:-1]) + ' or ' + names[-1]
    return 'Only %s files up to %d MB can be uploaded.' % (joined, MAX_MB)


def _read(upload, size=-1):
    try:
        upload.seek(0)
    except (AttributeError, OSError, ValueError):
        pass
    data = upload.read(size)
    try:
        upload.seek(0)
    except (AttributeError, OSError, ValueError):
        pass
    return data if isinstance(data, bytes) else str(data or '').encode('utf-8')


def _pdf(upload):
    return '' if _read(upload, 8).startswith(b'%PDF-') else 'is not a real PDF'


def _image(upload):
    head = _read(upload, 16)
    real = (head.startswith(b'\x89PNG\r\n\x1a\n') or head.startswith(b'\xff\xd8\xff')
            or head[:6] in (b'GIF87a', b'GIF89a') or (head[:4] == b'RIFF' and head[8:12] == b'WEBP'))
    return '' if real else 'is not a real PNG, JPEG, GIF or WEBP picture'


def _formula(cell):
    if not cell or cell[0] not in FORMULA_SIGNS:
        return False
    if cell in ('+', '-'):
        return False
    if cell[0] in '+-':
        try:
            float(cell)
        except ValueError:
            return True
        return False
    return True


def _csv(upload):
    data = _read(upload)
    if b'\x00' in data:
        return 'is not a text file'
    try:
        text = data.decode('utf-8-sig')
    except UnicodeDecodeError:
        return 'is not UTF-8 text'
    if text.lstrip()[:1] == '<':
        return 'is a web page, not a CSV'
    try:
        for number, row in enumerate(csv.reader(io.StringIO(text, newline='')), start=1):
            if any(_formula(cell) for cell in row):
                return 'has a cell on row %d that starts with =, +, -, @ (a spreadsheet formula)' % number
    except csv.Error:
        return 'is not a valid CSV'
    return ''


def _docx(upload):
    try:
        upload.seek(0)
        with zipfile.ZipFile(upload) as archive:
            parts = archive.infolist()
            names = {part.filename for part in parts}
            if len(parts) > MAX_ZIP_ENTRIES or sum(part.file_size for part in parts) > MAX_ZIP_BYTES:
                return 'is too large once unpacked'
            if '[Content_Types].xml' not in names or 'word/document.xml' not in names:
                return 'is not a Word document'
            lowered = [name.lower() for name in names]
            if any(name.endswith('vbaproject.bin') or name.startswith('word/activex') for name in lowered):
                return 'holds macros'
            for part in parts:
                if part.filename != '[Content_Types].xml' and not part.filename.endswith('.rels'):
                    continue
                if part.file_size > MAX_PART_BYTES:
                    return 'is not a Word document'
                text = archive.read(part.filename).decode('utf-8', 'replace')
                if 'macroEnabled' in text:
                    return 'holds macros'
                for relationship in RELATIONSHIP_RE.findall(text):
                    if EXTERNAL_RE.search(relationship) and not HYPERLINK_RE.search(relationship):
                        return 'loads a file from outside the document'
    except (zipfile.BadZipFile, zipfile.LargeZipFile, KeyError, OSError, RuntimeError, ValueError, EOFError):
        return 'is not a Word document'
    finally:
        try:
            upload.seek(0)
        except (AttributeError, OSError, ValueError):
            pass
    return ''


CHECKS = {'pdf': _pdf, 'image': _image, 'csv': _csv, 'docx': _docx}


def _size(upload):
    size = getattr(upload, 'size', None)
    return len(_read(upload)) if size is None else int(size)


def check_upload(upload, name=None, kinds=None):
    """Raises ValidationError unless the file is one of the kinds (the plan's by default) and within the size cap: the
    name's ending picks the kind, and the file's own bytes must be that kind."""
    kinds = tuple(kinds or ALLOWED)
    name = os.path.basename(str(name or getattr(upload, 'name', '') or '')).lower()
    size = _size(upload)
    if size > MAX_MB * 1024 * 1024:
        raise ValidationError('%s This file is %.1f MB.' % (allowed_text(kinds), size / (1024 * 1024)))
    ending = os.path.splitext(name)[1]
    kind = next((k for k in kinds if ending in EXTENSIONS[k]), None)
    if kind is None:
        raise ValidationError(allowed_text(kinds))
    problem = 'is empty' if size == 0 else CHECKS[kind](upload)
    if problem:
        raise ValidationError('%s This file %s.' % (allowed_text(kinds), problem))
